export function renderMixerLayout(document,ids){
  document.querySelector('.mixer').innerHTML=`<div class="mixer-heading">FOUR CHANNELS <span>ONE MIX</span></div><label class="sync-source-label">SYNC LEADER<select id="sync-master" aria-label="Sync leader">${ids.map(id=>`<option value="${id}">Deck ${id.toUpperCase()}</option>`).join('')}</select></label><div id="eq-controls" class="four-channels">${ids.map((id,index)=>`<section class="channel-strip channel-${id}" aria-label="Deck ${id.toUpperCase()} mixer channel"><h3>${id.toUpperCase()}</h3>${['high','mid','low','filter'].map(name=>`<label class="strip-control">${name==='filter'?'LPF':name.toUpperCase()}<input type="range" id="${name}-${id}" aria-label="Deck ${id.toUpperCase()} ${name}" min="${name==='filter'?0:-24}" max="${name==='filter'?100:12}" step="1" value="${name==='filter'?100:0}"><output class="eq-value">${name==='filter'?'OPEN':'0 dB'}</output></label>`).join('')}<div class="strip-fader"><label for="volume-${id}">LEVEL</label><div><input id="volume-${id}" aria-label="Deck ${id.toUpperCase()} volume" type="range" min="0" max="1" step="0.01" value="0.8"><meter id="vu-${id}" aria-label="Deck ${id.toUpperCase()} level" min="0" max="1" value="0"></meter></div></div><label class="strip-route">XFADE<select id="assignment-${id}" aria-label="Deck ${id.toUpperCase()} crossfader assignment"><option value="left" ${index%2===0?'selected':''}>LEFT</option><option value="thru">THRU</option><option value="right" ${index%2===1?'selected':''}>RIGHT</option></select></label></section>`).join('')}</div><div class="crossfade"><div><span>LEFT</span><label for="crossfade">CROSSFADER</label><span>RIGHT</span></div><input id="crossfade" type="range" min="0" max="1" step="0.01" value="0.5"><button id="center-fade" class="tiny">CENTER</button></div><div class="master"><label for="master">MASTER <output id="master-value">75%</output></label><input id="master" type="range" min="0" max="1" step="0.01" value="0.75"><meter id="master-meter" aria-label="Master output level" min="0" max="1" value="0"></meter></div><p class="routing-hint">LEFT / RIGHT follow the crossfader. THRU bypasses it. PFL stays independent.</p>`;
}
